return $input.all().map(item => {
  const d = item.json;
  const maske = t => String(t || '')
    .replace(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '[E-MAIL]')
    .replace(/\+?\d[\d\s\/().-]{6,}\d/g, '[TELEFON]');
  const initialen = String(d.name || '').split(/\s+/).filter(Boolean)
    .map(w => w[0].toUpperCase() + '.').join(' ');
  return { json: { ...d, name: initialen, email: '[E-MAIL]', nachricht: maske(d.nachricht) } };
});

// Ordnet eine Kontaktanfrage von todorvankov.com ein.
// Erwartet im Body: name, email, nachricht (auch message oder text)
const eingang = $input.first().json;
const body = eingang.body || eingang;
const name = body.name || body.Name || 'unbekannt';
const email = body.email || body.Email || body['e-mail'] || '';
const nachricht = String(body.nachricht || body.message || body.text || '').trim();
const text = nachricht.toLowerCase();

const arten = [
  ['Jobangebot', ['stelle', 'position', 'bewerbung', 'recruit', 'karriere', 'vakanz', 'job', 'festanstellung', 'vorstellungsgespräch', 'vorstellungsgespraech']],
  ['Projektanfrage', ['projekt', 'auftrag', 'angebot', 'freelance', 'freiberuf', 'zusammenarbeit', 'honorar']],
  ['Frage zu Tools', ['maxscript', 'plugin', 'download', 'python', 'job search tool', 'pdf tool', 'script', 'tutorial']],
];

let art = 'Sonstiges';
for (const [name_, woerter] of arten) {
  if (woerter.some(w => text.includes(w))) { art = name_; break; }
}

// Spam: viele Links oder typische Spam-Wörter
const links = (text.match(/https?:\/\//g) || []).length;
if (links >= 2 || ['casino', 'bitcoin', 'crypto', 'viagra', 'seo-', 'backlink', 'gewinn'].some(w => text.includes(w))) {
  art = 'Spam';
}

let dringlichkeit = 'normal';
if (art === 'Jobangebot') dringlichkeit = 'hoch';
else if (art === 'Projektanfrage') dringlichkeit = 'mittel';
else if (art === 'Spam') dringlichkeit = 'keine';

return [{
  json: {
    name,
    email,
    nachricht,
    art,
    dringlichkeit,
    eingegangen: new Date().toISOString(),
  }
}];

const d = $input.first().json;
const zeit = d.eingegangen.slice(0, 19).replace(/:/g, '-').replace('T', '_');
const dateiname = `${zeit}_${d.art.replace(/\s+/g, '-')}.md`;

const gruss = '

Freundliche Grüße
Todor Vankov';
const entwuerfe = {
  'Jobangebot': 'Guten Tag,

vielen Dank für Ihre Nachricht und Ihr Interesse. Gern spreche ich mit Ihnen über die Stelle. Bitte schicken Sie mir die Stellenbeschreibung und nennen Sie mir zwei mögliche Termine für ein kurzes Telefonat.' + gruss,
  'Projektanfrage': 'Guten Tag,

vielen Dank für Ihre Anfrage. Damit ich einschätzen kann, ob ich helfen kann, beschreiben Sie mir bitte kurz das Ziel des Projekts, den Zeitrahmen und die vorhandenen Daten oder Systeme.' + gruss,
  'Frage zu Tools': 'Guten Tag,

vielen Dank für Ihre Frage. Ich antworte Ihnen gern dazu. Können Sie mir kurz sagen, wofür Sie das Werkzeug einsetzen möchten?' + gruss,
  'Sonstiges': 'Guten Tag,

vielen Dank für Ihre Nachricht. Ich melde mich in den nächsten zwei Tagen bei Ihnen.' + gruss,
  'Spam': ''
};
const entwurf = (d.art in entwuerfe ? entwuerfe[d.art] : entwuerfe['Sonstiges']) || 'Keine Antwort nötig (Spam).';

const text = `# Anfrage: ${d.art}

- Eingegangen: ${d.eingegangen}
- Dringlichkeit: ${d.dringlichkeit}
- Name: ${d.name}

${d.nachricht}

## Antwort-Entwurf (bitte prüfen, nicht automatisch senden)

${entwurf}
`;

return [{
  json: { dateiname },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), dateiname, 'text/markdown') }
}];
